/* test_leapc.c — LEAPC.S (the 1-word LEAPC for a target within +-32 KiB,
 * klaussCPU 3508f87) at and around the +-32 KiB boundary: 80 LEAPCs, forward
 * and backward, whose distances to their targets sweep +-156 bytes around
 * 32768 (test_leapc_cases.S, generated by gen_test_leapc.py).  Each loads
 * the word it points at.  Prints a line per wrong word and "=== ALL PASS ===".
 */
#include <stdio.h>
#include "test_leapc_cases.h"

extern void lp_run(unsigned *out);

int main(void) {
  unsigned out[LP_N];
  for (int i = 0; i < LP_N; i++) out[i] = 0;
  lp_run(out);
  int bad = 0;
  for (int i = 0; i < LP_N; i++)
    if (out[i] != lp_expect[i]) {
      if (bad < 20) printf("FAIL probe %d: read 0x%x, want 0x%x\n", i, out[i], lp_expect[i]);
      bad++;
    }
  if (bad) printf("FAILED: %d\n", bad);
  else printf("=== ALL PASS ===\n");
  return bad != 0;
}
